// The shape of reports/results.json, as far as the dashboard reads it. Generated by `drg report`.

export const GRADERS = ['reference_match', 'public_tests', 'hidden_security', 'hidden_tests', 'robust'] as const;
export type Grader = (typeof GRADERS)[number];

export const VARIANTS = [
  'ref',
  'alt1',
  'alt2',
  'partial',
  'overblock',
  'first_site_only',
  'hack_delete',
  'hack_public',
  'hack_tamper',
] as const;
export type Variant = (typeof VARIANTS)[number];
export const VALID: ReadonlySet<Variant> = new Set(['ref', 'alt1', 'alt2']);

export interface GraderSummary {
  valid_accepted: number;
  invalid_accepted: number;
  by_variant: Partial<Record<Variant, number>>;
}

export interface RedTeamGrader {
  fixes_accepted: number;
  fixes: number;
  hacks_accepted: number;
  hacks: number;
  fixes_rate: number | null;
  hacks_rate: number | null;
}

export type RedTeamSet = { status: string; recorded_at: string | null } & Record<Grader, RedTeamGrader>;

export interface Episode {
  reward: number;
  contained: number;
  benign_isolated: number;
  dc_isolated: number;
  caught: number;
  ticks: number;
}

export interface CurvePoint {
  reward: number;
  contained: number;
  benign_isolated: number;
  caught: number;
}

export interface Check {
  name: string;
  path: string;
  op: string;
  value: number;
  actual: number | null;
  ok: boolean;
}

export interface Results {
  generated_at: string;
  profile: string;
  study?: Record<Grader, GraderSummary>;
  study_tasks?: number;
  redteam?: Record<string, RedTeamSet>;
  rl?: {
    families: string[];
    policies: Record<string, Record<string, Episode>>;
    baselines: Record<'isolate_all' | 'do_nothing' | 'analyst', Record<string, Episode>>;
    curves: Record<string, CurvePoint[]>;
    analyst_threshold: number;
    seeds: number[];
    clone_accuracy: number | null;
    margin_vs_analyst: number;
    margin_vs_isolate_all: number;
    gain_over_cloning: number | null;
    benign_isolated_reduction: number | null;
  };
  heldout?: {
    policies: Record<string, Episode>;
    baselines: Record<'isolate_all' | 'do_nothing' | 'analyst', Episode>;
    robust_reward: number | null;
    margin_vs_analyst: number;
    recorded_at: string | null;
  };
  bench?: { soc_episodes_per_s: number; patch_grades_per_s: number };
  gate?: { floors: Check[]; targets: Check[] };
}

export function isResults(x: unknown): x is Results {
  if (typeof x !== 'object' || x === null) return false;
  const r = x as Record<string, unknown>;
  return typeof r.generated_at === 'string' && typeof r.profile === 'string';
}

/** A policy's results on one network family: the trained variants first, then the baselines. */
export function boardFor(r: Results, family: string): { key: string; ep: Episode }[] {
  if (family === 'heldout') {
    const h = r.heldout;
    if (!h) return [];
    return [
      ...Object.entries(h.policies).map(([key, ep]) => ({ key, ep })),
      ...Object.entries(h.baselines).map(([key, ep]) => ({ key, ep })),
    ];
  }
  const rl = r.rl;
  if (!rl) return [];
  const out: { key: string; ep: Episode }[] = [];
  for (const [key, fams] of Object.entries(rl.policies)) {
    const ep = fams[family];
    if (ep) out.push({ key, ep });
  }
  for (const [key, fams] of Object.entries(rl.baselines)) {
    const ep = fams[family];
    if (ep) out.push({ key, ep });
  }
  return out;
}
